//! Minimal stand-in for the `terminal_size` crate.
//!
//! Only the small subset of the API used by `clap` (`terminal_size()` with the
//! `Width`/`Height` newtypes) is provided. The size is obtained with the
//! `TIOCGWINSZ` ioctl on stdout, stderr and stdin (in that order).

use std::os::raw::{c_int, c_ulong};

/// Terminal width in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int;
    fn isatty(fd: c_int) -> c_int;
}

#[cfg(any(target_os = "linux", target_os = "android"))]
const TIOCGWINSZ: c_ulong = 0x5413;
#[cfg(not(any(target_os = "linux", target_os = "android")))]
const TIOCGWINSZ: c_ulong = 0x4008_7468;

fn size_of_fd(fd: c_int) -> Option<(Width, Height)> {
    // SAFETY: plain libc calls with a valid pointer to a properly sized struct.
    unsafe {
        if isatty(fd) != 1 {
            return None;
        }
        let mut ws = WinSize::default();
        if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) != 0 {
            return None;
        }
        if ws.ws_row > 0 && ws.ws_col > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}

/// Returns the size of the terminal attached to stdout, stderr or stdin.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_fd(1).or_else(|| size_of_fd(2)).or_else(|| size_of_fd(0))
}
EOF
echo done"}

