{"command":"cd /workspace && cat > src/cli.rs <<'EOF'
//! Command line interface.
//!
//! The interface is built with `clap`'s builder API. The option set, help
//! texts and colour theme mirror the documented behaviour of the tool.

use std::fmt::Write as _;

use clap::builder::styling::{AnsiColor, Effects, Styles};
use clap::builder::StyledStr;
use clap::error::{ContextKind, ContextValue, ErrorKind};
use clap::{value_parser, Arg, ArgAction, ArgGroup, ArgMatches, Command};

use crate::table::style::Style;
use crate::table::Alignment;

/// Colour theme used for `--help` and error messages.
const STYLES: Styles = Styles::styled()
    .header(AnsiColor::Yellow.on_default().effects(Effects::BOLD))
    .usage(AnsiColor::Yellow.on_default().effects(Effects::BOLD))
    .literal(AnsiColor::Green.on_default().effects(Effects::BOLD))
    .placeholder(AnsiColor::Cyan.on_default());

const STYLE_VALUES: [&str; 8] = [
    "none",
    "ascii",
    "ascii2",
    "sharp",
    "rounded",
    "reinforced",
    "markdown",
    "grid",
];

const ALIGN_VALUES: [&str; 3] = ["left", "center", "right"];

/// Identifiers of every argument, in declaration order.
const ALL_ARGS: [&str; 12] = [
    "file",
    "no_headers",
    "number",
    "tsv",
    "delimiter",
    "style",
    "padding",
    "indent",
    "sniff",
    "header_align",
    "body_align",
    "disable_pager",
];

/// Parsed, validated command line options.
#[derive(Debug, Clone)]
pub struct Args {
    /// File to view (`None` means standard input).
    pub file: Option<String>,
    /// The input has no header row.
    pub no_headers: bool,
    /// Prepend a column with line numbers.
    pub number: bool,
    /// Field delimiter (as a single byte).
    pub delimiter: u8,
    /// Border style.
    pub style: Style,
    /// Cell padding.
    pub padding: usize,
    /// Global indentation.
    pub indent: usize,
    /// Number of body rows to sniff for column widths (`0` = unlimited).
    pub sniff: usize,
    /// Alignment of the header cells.
    pub header_align: Alignment,
    /// Alignment of the body cells.
    pub body_align: Alignment,
    /// Do not pipe the output through a pager.
    pub disable_pager: bool,
}

fn build_command() -> Command {
    Command::new("csview")
        .version("1.3.4")
        .about("A high performance csv viewer with cjk/emoji support.")
        .next_line_help(true)
        .styles(STYLES)
        .arg(Arg::new("file").value_name("FILE").help("File to view"))
        .arg(
            Arg::new("no_headers")
                .short('H')
                .long("no-headers")
                .action(ArgAction::SetTrue)
                .help("Specify that the input has no header row"),
        )
        .arg(
            Arg::new("number")
                .short('n')
                .long("number")
                .action(ArgAction::SetTrue)
                .help("Prepend a column of line numbers to the table"),
        )
        .arg(
            Arg::new("tsv")
                .short('t')
                .long("tsv")
                .action(ArgAction::SetTrue)
                .conflicts_with("delimiter")
                .help("Use '\\t' as delimiter for tsv"),
        )
        .arg(
            Arg::new("delimiter")
                .short('d')
                .long("delimiter")
                .value_name("DELIMITER")
                .default_value(",")
                .value_parser(value_parser!(char))
                .help("Specify the field delimiter"),
        )
        .arg(
            Arg::new("style")
                .short('s')
                .long("style")
                .value_name("STYLE")
                .default_value("sharp")
                .value_parser(STYLE_VALUES)
                .help("Specify the border style"),
        )
        .arg(
            Arg::new("padding")
                .short('p')
                .long("padding")
                .value_name("PADDING")
                .default_value("1")
                .value_parser(value_parser!(usize))
                .help("Specify padding for table cell"),
        )
        .arg(
            Arg::new("indent")
                .short('i')
                .long("indent")
                .value_name("INDENT")
                .default_value("0")
                .value_parser(value_parser!(usize))
                .help("Specify global indent for table"),
        )
        .arg(
            Arg::new("sniff")
                .long("sniff")
                .value_name("LIMIT")
                .default_value("1000")
                .value_parser(value_parser!(usize))
                .help(
                    "Limit column widths sniffing to the specified number of rows. \
                     Specify \"0\" to cancel limit",
                ),
        )
        .arg(
            Arg::new("header_align")
                .long("header-align")
                .value_name("HEADER_ALIGN")
                .default_value("center")
                .value_parser(ALIGN_VALUES)
                .help("Specify the alignment of the table header"),
        )
        .arg(
            Arg::new("body_align")
                .long("body-align")
                .value_name("BODY_ALIGN")
                .default_value("left")
                .value_parser(ALIGN_VALUES)
                .help("Specify the alignment of the table body"),
        )
        .arg(
            Arg::new("disable_pager")
                .short('P')
                .long("disable-pager")
                .action(ArgAction::SetTrue)
                .help("Disable pager"),
        )
        .group(ArgGroup::new("Args").multiple(true).args(ALL_ARGS))
}

/// Usage line shown for unknown `--long` arguments once other arguments have
/// already been seen: every member of the implicit argument group is listed.
fn group_usage(cmd: &Command) -> StyledStr {
    let styles = cmd.get_styles();
    let usage = styles.get_usage();
    let literal = styles.get_literal();
    let bin = cmd
        .get_bin_name()
        .unwrap_or_else(|| cmd.get_name())
        .to_owned();

    let mut members: Vec<String> = Vec::new();
    for id in ALL_ARGS {
        let arg = cmd
            .get_arguments()
            .find(|a| a.get_id().as_str() == id)
            .expect("argument exists");
        if arg.is_positional() {
            members.push(
                arg.get_value_names()
                    .and_then(|v| v.first())
                    .map(|v| v.to_string())
                    .unwrap_or_else(|| arg.get_id().to_string().to_uppercase()),
            );
        } else {
            members.push(arg.to_string());
        }
    }

    let mut out = StyledStr::new();
    let _ = write!(out, "{}Usage:{} ", usage.render(), usage.render_reset());
    let _ = write!(out, "{}{}{} ", literal.render(), bin, literal.render_reset());
