fn adjust_unknown_argument_usage(cmd: &mut Command, err: &mut clap::Error) {
    if err.kind() != ErrorKind::UnknownArgument {
        return;
    }
    let is_long = matches!(
        err.get(ContextKind::InvalidArg),
        Some(ContextValue::String(arg)) if arg.starts_with("--")
