    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Io(err) => err.fmt(f),
            Error::Utf8 {
                pos,
                field,
                valid_up_to,
            } => write!(
                f,
                "CSV parse error: record {} (line {}, field: {}, byte: {}): \
                 invalid utf-8: invalid UTF-8 in field {} near byte index {}",
                pos.record, pos.line, field, pos.byte, field, valid_up_to
            ),
            Error::UnequalLengths {
                pos,
                expected_len,
                len,
            } => write!(
                f,
                "CSV error: record {} (line: {}, byte: {}): \
                 found record with {} fields, but the previous record has {} fields",
                pos.record, pos.line, pos.byte, len, expected_len
            ),
        }
    }
}

impl std::error::Error for Error {}

impl From<io::Error> for Error {
    fn from(err: io::Error) -> Self {
        Error::Io(err)
    }
}

/// Parser state between two input bytes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Before the first byte of a record (leading terminators are skipped).
    StartRecord,
    /// At the start of a field.
    StartField,
    /// Inside an unquoted field.
    InField,
    /// Inside a quoted field.
    InQuotedField,
    /// Just after a quote inside a quoted field.
    AfterQuote,
}

/// A streaming CSV reader over any buffered input.
pub struct Reader<R> {
    rdr: R,
    delimiter: u8,
    pos: Position,
    first_field_count: Option<u64>,
    has_read: bool,
    eof: bool,
}

impl<R: BufRead> Reader<R> {
    /// Creates a reader using `delimiter` as field separator.
    pub fn new(rdr: R, delimiter: u8) -> Self {
        Reader {
            rdr,
            delimiter,
            pos: Position {
                byte: 0,
                line: 1,
                record: 0,
            },
            first_field_count: None,
            has_read: false,
            eof: false,
        }
    }

    /// Reads the next record. Returns `Ok(None)` once the input is exhausted.
    pub fn read_record(&mut self) -> Result<Option<Vec<String>>, Error> {
        let start = self.pos;
        if self.eof {
            return Ok(None);
        }

        let mut fields: Vec<Vec<u8>> = Vec::new();
        let mut cur: Vec<u8> = Vec::new();
        let mut state = State::StartRecord;

        'read: loop {
            let buf = match self.rdr.fill_buf() {
                Ok(buf) => buf,
                Err(err) => {
                    self.eof = true;
                    return Err(Error::Io(err));
                }
            };

            if buf.is_empty() {
                // End of input.
                if state == State::StartRecord {
                    self.eof = true;
                    return Ok(None);
                }
                fields.push(std::mem::take(&mut cur));
                break 'read;
            }

            let mut i = 0;
            if !self.has_read {
                self.has_read = true;
                if buf.starts_with(BOM) {
                    i = BOM.len();
                }
            }

            let mut finished = false;
            while i < buf.len() {
                let b = buf[i];
                let is_term = b == b'\n' || b == b'\r';
                match state {
                    State::StartRecord => {
                        if is_term {
                            if b == b'\n' {
                                self.pos.line += 1;
                            }
                            i += 1;
                            continue;
                        }
                        // Re-process this byte as the start of a field.
                        state = State::StartField;
                        continue;
                    }
                    State::StartField => {
                        if b == QUOTE {
                            state = State::InQuotedField;
                        } else if b == self.delimiter {
                            fields.push(std::mem::take(&mut cur));
                        } else if is_term {
                            fields.push(std::mem::take(&mut cur));
                            finished = true;
                        } else {
                            cur.push(b);
                            state = State::InField;
                        }
                    }
                    State::InField => {
                        if b == self.delimiter {
                            fields.push(std::mem::take(&mut cur));
                            state = State::StartField;
                        } else if is_term {
                            fields.push(std::mem::take(&mut cur));
                            finished = true;
                        } else {
                            cur.push(b);
                        }
                    }
                    State::InQuotedField => {
                        if b == QUOTE {
                            state = State::AfterQuote;
                        } else {
                            cur.push(b);
                        }
                    }
                    State::AfterQuote => {
                        if b == QUOTE {
                            cur.push(QUOTE);
                            state = State::InQuotedField;
                        } else if b == self.delimiter {
                            fields.push(std::mem::take(&mut cur));
                            state = State::StartField;
                        } else if is_term {
                            fields.push(std::mem::take(&mut cur));
                            finished = true;
                        } else {
                            cur.push(b);
                            state = State::InField;
                        }
                    }
                }
                if b == b'\n' {
                    self.pos.line += 1;
                }
                i += 1;
                if finished {
                    break;
                }
            }

            self.rdr.consume(i);
            self.pos.byte += i as u64;
            if finished {
                break 'read;
            }
        }

        self.pos.record += 1;

        let len = fields.len() as u64;
        match self.first_field_count {
            None => self.first_field_count = Some(len),
            Some(expected) if expected != len => {
                return Err(Error::UnequalLengths {
                    pos: start,
                    expected_len: expected,
                    len,
                });
            }
            Some(_) => {}
        }

        let mut record = Vec::with_capacity(fields.len());
        for (index, field) in fields.into_iter().enumerate() {
            match String::from_utf8(field) {
                Ok(s) => record.push(s),
                Err(err) => {
                    return Err(Error::Utf8 {
                        pos: start,
                        field: index,
                        valid_up_to: err.utf8_error().valid_up_to(),
                    });
                }
            }
        }
        Ok(Some(record))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn read_all(data: &str) -> Result<Vec<Vec<String>>, Error> {
        let mut rdr = Reader::new(data.as_bytes(), b',');
        let mut out = Vec::new();
        while let Some(rec) = rdr.read_record()? {
            out.push(rec);
        }
        Ok(out)
    }

    #[test]
    fn simple() {
        let rows = read_all("a,b\n1,2\n").unwrap();
        assert_eq!(rows, vec![vec!["a", "b"], vec!["1", "2"]]);
    }

    #[test]
    fn quotes_and_blank_lines() {
        let rows = read_all("a,b\n\n\"x,1\",\"he said \"\"hi\"\"\"\n\"multi\nline\",y").unwrap();
        assert_eq!(
            rows,
            vec![
                vec!["a", "b"],
                vec!["x,1", "he said \"hi\""],
                vec!["multi\nline", "y"],
            ]
        );
    }

    #[test]
    fn unequal_lengths_position() {
        let err = read_all("a,b,c\r\n1,2\r\n").unwrap_err();
        match err {
            Error::UnequalLengths { pos, expected_len, len } => {
                assert_eq!(pos, Position { byte: 6, line: 1, record: 1 });
                assert_eq!((expected_len, len), (3, 2));
            }
            other => panic!("unexpected {other:?}"),
        }
    }

    #[test]
    fn bom_is_skipped_but_counted() {
        let mut rdr = Reader::new(&b"\xef\xbb\xbf\"a\",b\n1,2\n"[..], b',');
        let first = rdr.read_record().unwrap().unwrap();
        assert_eq!(first, vec!["a", "b"]);
        assert_eq!(rdr.pos.byte, 9);
    }
}
