    /// Rule drawn above the first row.
    pub fn top(&self) -> Option<Rule> {
        match self {
            Style::None | Style::Ascii2 | Style::Markdown => None,
            Style::Ascii => Some(ASCII_RULE),
            Style::Sharp | Style::Grid => Some(rule("┌", "─", "┬", "┐")),
            Style::Rounded => Some(rule("╭", "─", "┬", "╮")),
            Style::Reinforced => Some(rule("┏", "─", "┬", "┓")),
        }
    }

    /// Rule drawn between the header and the body.
    pub fn header_separator(&self) -> Option<Rule> {
        match self {
            Style::None => None,
            Style::Ascii => Some(ASCII_RULE),
            Style::Ascii2 => Some(rule(" ", "-", "+", " ")),
            Style::Markdown => Some(rule("|", "-", "|", "|")),
            Style::Sharp | Style::Rounded | Style::Reinforced | Style::Grid => Some(LIGHT_MIDDLE),
        }
    }

    /// Rule drawn between two body rows.
    pub fn row_separator(&self) -> Option<Rule> {
        match self {
            Style::Grid => Some(LIGHT_MIDDLE),
            _ => None,
        }
    }

