            Style::Sharp | Style::Grid => Some(rule("└", "─", "┴", "┘")),
            Style::Rounded => Some(rule("╰", "─", "┴", "╯")),
            Style::Reinforced => Some(rule("┗", "─", "┴", "┛")),
        }
    }

    /// Vertical borders of a row.
    pub fn borders(&self) -> Borders {
        match self {
            Style::None => borders("", "", ""),
            Style::Ascii | Style::Markdown => ASCII_BORDERS,
            Style::Ascii2 => borders(" ", "|", " "),
            Style::Sharp | Style::Rounded | Style::Reinforced | Style::Grid => LIGHT_BORDERS,
        }
    }
}

/// Writes a horizontal rule spanning the given column widths.
///
/// `widths` are the content widths of the columns; each column is widened by
/// `padding` on both sides.
pub fn write_rule<W: Write>(
    out: &mut W,
    rule: &Rule,
    widths: &[usize],
    padding: usize,
    indent: usize,
) -> io::Result<()> {
    write!(out, "{:indent$}", "")?;
    out.write_all(rule.left.as_bytes())?;
    for (i, width) in widths.iter().enumerate() {
        if i > 0 {
            out.write_all(rule.cross.as_bytes())?;
        }
        let total = width + 2 * padding;
        out.write_all(rule.fill.repeat(total).as_bytes())?;
    }
    out.write_all(rule.right.as_bytes())?;
    out.write_all(b"\n")
}
