//! Streaming table renderer.

pub mod row;
pub mod style;

use std::io::{BufRead, Write};

use unicode_width::UnicodeWidthStr;

use crate::csv::Reader;
use crate::Error;
use style::Style;

/// Horizontal alignment of cell contents.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Alignment {
    Left,
    Center,
    Right,
}

/// Rendering options.
#[derive(Debug, Clone)]
pub struct Options {
    /// Border style.
    pub style: Style,
    /// Spaces on each side of a cell's content.
    pub padding: usize,
    /// Spaces before every line.
    pub indent: usize,
    /// Number of body rows used to determine the column widths (`0` = all).
    pub sniff: usize,
    /// Alignment of header cells.
    pub header_align: Alignment,
    /// Alignment of body cells.
    pub body_align: Alignment,
    /// Prepend a line number column.
    pub number: bool,
    /// The input has no header row.
    pub no_headers: bool,
}

/// Widens `widths` so that every cell of `row` fits.
fn update_widths(widths: &mut Vec<usize>, row: &[String]) {
    for (i, cell) in row.iter().enumerate() {
        let w = cell.width();
        match widths.get_mut(i) {
            Some(current) => *current = (*current).max(w),
            None => widths.push(w),
        }
    }
}

struct Renderer<'a, W: Write> {
    out: &'a mut W,
    opts: &'a Options,
    widths: Vec<usize>,
    /// Whether a body row has already been written.
    body_started: bool,
}

impl<W: Write> Renderer<'_, W> {
    fn rule(&mut self, rule: Option<style::Rule>) -> Result<(), Error> {
        if let Some(rule) = rule {
            style::write_rule(
                self.out,
                &rule,
                &self.widths,
                self.opts.padding,
                self.opts.indent,
            )?;
        }
        Ok(())
    }

    fn header(&mut self, cells: &[String]) -> Result<(), Error> {
        let borders = self.opts.style.borders();
        row::write_row(
            self.out,
            cells,
            &self.widths,
            &borders,
            self.opts.padding,
            self.opts.indent,
            self.opts.header_align,
        )?;
        Ok(())
    }

    fn body_row(&mut self, cells: &[String]) -> Result<(), Error> {
        if !self.body_started {
            if !self.opts.no_headers {
                self.rule(self.opts.style.header_separator())?;
            }
        } else {
            self.rule(self.opts.style.row_separator())?;
        }
        self.body_started = true;
        let borders = self.opts.style.borders();
        row::write_row(
            self.out,
            cells,
            &self.widths,
            &borders,
            self.opts.padding,
            self.opts.indent,
            self.opts.body_align,
        )?;
        Ok(())
    }
}

/// Reads every record from `rdr` and writes the rendered table to `out`.
///
/// The header (when present) and the first `sniff` body rows are read up
/// front to determine the column widths; the remaining rows are streamed and
/// cells wider than their column are truncated.
pub fn render<R: BufRead, W: Write>(
    rdr: &mut Reader<R>,
    out: &mut W,
    opts: &Options,
) -> Result<(), Error> {
    let mut widths: Vec<usize> = Vec::new();

    let mut header_row: Vec<String> = Vec::new();
    if opts.number {
        header_row.push("#".to_owned());
    }
    if !opts.no_headers {
        if let Some(fields) = rdr.read_record()? {
            header_row.extend(fields);
        }
    }
    update_widths(&mut widths, &header_row);

    let mut line_no: usize = 0;
    let make_row = |fields: Vec<String>, line_no: usize| -> Vec<String> {
        if opts.number {
            let mut row = Vec::with_capacity(fields.len() + 1);
            row.push(line_no.to_string());
            row.extend(fields);
            row
        } else {
            fields
        }
    };

    let limit = if opts.sniff == 0 {
        usize::MAX
    } else {
        opts.sniff
    };
    let mut sniffed: Vec<Vec<String>> = Vec::new();
    while sniffed.len() < limit {
        match rdr.read_record()? {
            Some(fields) => {
                line_no += 1;
                let row = make_row(fields, line_no);
                update_widths(&mut widths, &row);
                sniffed.push(row);
            }
            None => break,
        }
    }

    let mut renderer = Renderer {
        out,
        opts,
        widths,
        body_started: false,
    };

    renderer.rule(opts.style.top())?;
    if !opts.no_headers {
        renderer.header(&header_row)?;
    }
    for row in &sniffed {
        renderer.body_row(row)?;
    }
    drop(sniffed);
    while let Some(fields) = rdr.read_record()? {
        line_no += 1;
        let row = make_row(fields, line_no);
        renderer.body_row(&row)?;
    }
    renderer.rule(opts.style.bottom())?;
    Ok(())
}
