//! Pipes the output through `less` when standard output is a terminal.
//!
//! The process forks: the child continues running the viewer with its standard
//! output connected to a pipe, while the parent turns itself into the pager
//! (`less`, with `LESS=-SF`) reading from that pipe. If the pager cannot be
//! started the parent simply carries on as the viewer itself.

use std::ffi::CString;
use std::os::raw::{c_char, c_int};
use std::ptr;

extern "C" {
    fn isatty(fd: c_int) -> c_int;
    fn pipe(fds: *mut c_int) -> c_int;
    fn fork() -> c_int;
    fn dup2(oldfd: c_int, newfd: c_int) -> c_int;
    fn close(fd: c_int) -> c_int;
    fn execvp(file: *const c_char, argv: *const *const c_char) -> c_int;
    fn setenv(name: *const c_char, value: *const c_char, overwrite: c_int) -> c_int;
}

const STDIN_FILENO: c_int = 0;
const STDOUT_FILENO: c_int = 1;
const PAGER: &str = "less";
const PAGER_ENV: (&str, &str) = ("LESS", "-SF");

/// Returns `true` when standard output is attached to a terminal.
pub fn stdout_is_terminal() -> bool {
    // SAFETY: `isatty` only inspects the descriptor.
    unsafe { isatty(STDOUT_FILENO) == 1 }
}

/// Sets up the pager if standard output is a terminal.
pub fn setup() {
    if !stdout_is_terminal() {
        return;
    }

    let mut fds: [c_int; 2] = [0; 2];
    // SAFETY: `fds` is a valid two-element array.
    if unsafe { pipe(fds.as_mut_ptr()) } != 0 {
        return;
    }
    let (pager_stdin, viewer_stdout) = (fds[0], fds[1]);

    // SAFETY: plain POSIX calls; the descriptors come from `pipe` above.
    unsafe {
        match fork() {
            -1 => {
                close(pager_stdin);
                close(viewer_stdout);
            }
            0 => {
                // Child: keep running the viewer, writing into the pipe.
                dup2(viewer_stdout, STDOUT_FILENO);
                close(pager_stdin);
            }
            _ => {
                // Parent: become the pager, reading from the pipe.
                dup2(pager_stdin, STDIN_FILENO);
                close(viewer_stdout);
                exec_pager();
                // Reaching this point means the pager could not be started;
                // continue as the viewer.
            }
        }
    }
}

unsafe fn exec_pager() {
    let (name, value) = PAGER_ENV;
    if let (Ok(name), Ok(value)) = (CString::new(name), CString::new(value)) {
        setenv(name.as_ptr(), value.as_ptr(), 1);
    }
    let program = match CString::new(PAGER) {
        Ok(p) => p,
        Err(_) => return,
    };
    let argv: [*const c_char; 2] = [program.as_ptr(), ptr::null()];
    execvp(program.as_ptr(), argv.as_ptr());
}
