//! csview: a high performance csv viewer with cjk/emoji support.

mod cli;
mod csv;
mod pager;
mod table;

use std::fmt;
use std::fs::File;
use std::io::{self, BufRead, BufReader, BufWriter, Write};
use std::process;

/// Any error that aborts the program.
#[derive(Debug)]
pub enum Error {
    /// Reading or parsing the input failed.
    Csv(csv::Error),
    /// Writing the output failed.
    Io(io::Error),
}

impl Error {
    /// `true` when the output side went away (e.g. the pager was closed).
    fn is_broken_pipe(&self) -> bool {
        matches!(self, Error::Io(err) if err.kind() == io::ErrorKind::BrokenPipe)
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Csv(err) => err.fmt(f),
            Error::Io(err) => err.fmt(f),
        }
    }
}

impl From<csv::Error> for Error {
    fn from(err: csv::Error) -> Self {
        Error::Csv(err)
    }
}

impl From<io::Error> for Error {
    fn from(err: io::Error) -> Self {
        Error::Io(err)
    }
}

fn open_input(path: Option<&str>) -> Result<Box<dyn BufRead>, Error> {
    match path {
        Some(path) => {
            let file = File::open(path).map_err(csv::Error::Io)?;
            Ok(Box::new(BufReader::with_capacity(1 << 16, file)))
        }
        None => Ok(Box::new(BufReader::with_capacity(1 << 16, io::stdin()))),
    }
}

fn run(args: &cli::Args) -> Result<(), Error> {
    let input = open_input(args.file.as_deref())?;
    let mut rdr = csv::Reader::new(input, args.delimiter);

    let opts = table::Options {
        style: args.style,
        padding: args.padding,
        indent: args.indent,
        sniff: args.sniff,
        header_align: args.header_align,
        body_align: args.body_align,
        number: args.number,
        no_headers: args.no_headers,
    };

    let stdout = io::stdout();
    let mut out = BufWriter::with_capacity(1 << 16, stdout.lock());
    let result = table::render(&mut rdr, &mut out, &opts);
    let flushed = out.flush();
    result?;
    flushed?;
    Ok(())
}

fn main() {
    let args = cli::parse();

    if !args.disable_pager {
        pager::setup();
    }

    if let Err(err) = run(&args) {
        if err.is_broken_pipe() {
            process::exit(0);
        }
        eprintln!("csview: {err}");
        process::exit(1);
    }
}
