s=open(p).read()
start = s.index('struct Renderer')
new_tail = '''/// Source of body rows: the rows read while sniffing, followed by the rows
/// still to be read from the input.
struct Rows<'a, R> {
    rdr: &'a mut Reader<R>,
    sniffed: std::collections::VecDeque<Vec<String>>,
    number: bool,
    line_no: usize,
}

impl<R: BufRead> Rows<'_, R> {
    fn make_row(&mut self, fields: Vec<String>) -> Vec<String> {
        self.line_no += 1;
        if self.number {
            let mut row = Vec::with_capacity(fields.len() + 1);
            row.push(self.line_no.to_string());
            row.extend(fields);
            row
        } else {
            fields
        }
    }

    /// Reads one more row from the input (used while sniffing).
    fn read(&mut self) -> Result<Option<Vec<String>>, Error> {
        match self.rdr.read_record()? {
            Some(fields) => Ok(Some(self.make_row(fields))),
            None => Ok(None),
        }
    }

    /// Returns the next row, `None` at the end of the input or the error that
    /// interrupted reading.
    fn next(&mut self) -> Option<Result<Vec<String>, Error>> {
        if let Some(row) = self.sniffed.pop_front() {
            return Some(Ok(row));
        }
        self.read().transpose()
    }
}

/// Reads every record from `rdr` and writes the rendered table to `out`.
///
/// The header (when present) and the first `sniff` body rows are read up
/// front to determine the column widths; the remaining rows are streamed and
/// cells wider than their column are truncated.
pub fn render<R: BufRead, W: Write>(
    rdr: &mut Reader<R>,
    out: &mut W,
    opts: &Options,
) -> Result<(), Error> {
    let mut widths: Vec<usize> = Vec::new();

    let mut header_row: Vec<String> = Vec::new();
    if opts.number {
        header_row.push("#".to_owned());
    }
    if !opts.no_headers {
        if let Some(fields) = rdr.read_record()? {
            header_row.extend(fields);
        }
    }
    update_widths(&mut widths, &header_row);

    let mut rows = Rows {
        rdr,
        sniffed: std::collections::VecDeque::new(),
        number: opts.number,
        line_no: 0,
    };
    let limit = if opts.sniff == 0 {
        usize::MAX
    } else {
        opts.sniff
    };
    while rows.sniffed.len() < limit {
        match rows.read()? {
            Some(row) => {
                update_widths(&mut widths, &row);
                rows.sniffed.push_back(row);
            }
            None => break,
        }
    }

    let style = opts.style;
    let borders = style.borders();
    let rule = |out: &mut W, rule: Option<style::Rule>| -> Result<(), Error> {
        if let Some(rule) = rule {
            style::write_rule(out, &rule, &widths, opts.padding, opts.indent)?;
        }
        Ok(())
    };

    rule(out, style.top())?;
    let mut next = rows.next();
    if !opts.no_headers {
        row::write_row(
            out,
            &header_row,
            &widths,
            &borders,
            opts.padding,
            opts.indent,
            opts.header_align,
        )?;
        if next.is_some() {
            rule(out, style.header_separator())?;
        }
    }
    while let Some(item) = next {
        let row = item?;
        row::write_row(
            out,
            &row,
            &widths,
            &borders,
            opts.padding,
            opts.indent,
            opts.body_align,
        )?;
        // A separator follows the row whenever something comes after it, even
        // if that turns out to be an error.
        next = rows.next();
        if next.is_some() {
            rule(out, style.row_separator())?;
        }
    }
    rule(out, style.bottom())?;
    Ok(())
}
