//! Rendering of a single table row.

use std::io::{self, Write};

use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthStr;

use super::style::Borders;
use super::Alignment;

/// A row of cells together with the layout needed to draw it.
pub struct Row<'a> {
    pub cells: &'a [String],
    pub widths: &'a [usize],
    pub borders: &'a Borders,
    pub padding: usize,
    pub indent: usize,
    pub align: Alignment,
}

impl Row<'_> {
    pub fn write<W: Write>(&self, out: &mut W) -> io::Result<()> {
        write!(out, "{:indent$}", "", indent = self.indent)?;
        out.write_all(self.borders.left.as_bytes())?;
        let padding = self.padding;
        for (i, width) in self.widths.iter().enumerate() {
            if i > 0 {
                out.write_all(self.borders.separator.as_bytes())?;
            }
            write!(out, "{:padding$}", "")?;
            let content = self.cells.get(i).map(String::as_str).unwrap_or("");
            let (text, text_width) = truncate(content, *width);
            let fill = width.saturating_sub(text_width);
            let (before, after) = match self.align {
                Alignment::Left => (0, fill),
                Alignment::Right => (fill, 0),
                Alignment::Center => (fill / 2, fill - fill / 2),
            };
            write!(out, "{:before$}", "")?;
            out.write_all(text.as_bytes())?;
            write!(out, "{:after$}", "")?;
            write!(out, "{:padding$}", "")?;
        }
        out.write_all(self.borders.right.as_bytes())?;
        out.write_all(b"\n")
    }
}

/// Returns the longest prefix of `s` whose display width does not exceed
/// `max_width`, together with the width of that prefix.
///
/// The string is cut at grapheme cluster boundaries so that combining marks
/// and emoji sequences are never split.
pub fn truncate(s: &str, max_width: usize) -> (&str, usize) {
    let mut end = 0;
    let mut width = 0;
    for (index, grapheme) in s.grapheme_indices(true) {
        let w = grapheme.width();
        if width + w > max_width {
            break;
        }
        width += w;
        end = index + grapheme.len();
    }
    (&s[..end], width)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn truncate_ascii() {
        assert_eq!(truncate("hello", 3), ("hel", 3));
        assert_eq!(truncate("hi", 5), ("hi", 2));
        assert_eq!(truncate("", 5), ("", 0));
    }

    #[test]
    fn truncate_wide() {
        assert_eq!(truncate("中文字", 5), ("中文", 4));
        assert_eq!(truncate("1中文字", 5), ("1中文", 5));
    }

    #[test]
    fn truncate_keeps_clusters() {
        let family = "\u{1F468}\u{200D}\u{1F469}\u{200D}\u{1F467}";
        assert_eq!(truncate(family, 3), (family, 2));
        assert_eq!(truncate("abce\u{301}", 3), ("abc", 3));
        assert_eq!(truncate("abe\u{301}", 3), ("abe\u{301}", 3));
    }

    #[test]
    fn row_layout() {
        let cells = vec!["ab".to_owned(), "中文字".to_owned()];
        let widths = [4, 4];
        let borders = Borders {
            left: "|",
            separator: "|",
            right: "|",
        };
        let mut out = Vec::new();
        Row {
            cells: &cells,
            widths: &widths,
            borders: &borders,
            padding: 1,
            indent: 2,
            align: Alignment::Center,
        }
        .write(&mut out)
        .unwrap();
        assert_eq!(String::from_utf8(out).unwrap(), "  |  ab  | 中文 |\n");
    }
}
EOF
