{"command":"cd /workspace && cat > src/table/style.rs <<'EOF'
//! Border styles.
//!
//! A style describes which horizontal rules are drawn (above the table,
//! between the header and the body, between body rows and below the table)
//! and which vertical borders surround the cells of a row.

use std::io::{self, Write};

/// Pieces used to draw a horizontal rule.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Rule {
    /// Leftmost character.
    pub left: &'static str,
    /// Character repeated to fill a column.
    pub fill: &'static str,
    /// Character placed between two columns.
    pub cross: &'static str,
    /// Rightmost character.
    pub right: &'static str,
}

/// Vertical borders used when drawing a row of cells.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Borders {
    /// Text placed before the first cell.
    pub left: &'static str,
    /// Text placed between two cells.
    pub separator: &'static str,
    /// Text placed after the last cell.
    pub right: &'static str,
}

const fn rule(
    left: &'static str,
    fill: &'static str,
    cross: &'static str,
    right: &'static str,
) -> Rule {
    Rule {
        left,
        fill,
        cross,
        right,
    }
}

const fn borders(left: &'static str, separator: &'static str, right: &'static str) -> Borders {
    Borders {
        left,
        separator,
        right,
    }
}

const LIGHT_MIDDLE: Rule = rule("├", "─", "┼", "┤");
const LIGHT_BORDERS: Borders = borders("│", "│", "│");
const ASCII_RULE: Rule = rule("+", "-", "+", "+");
const ASCII_BORDERS: Borders = borders("|", "|", "|");

/// The available table styles.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Style {
    /// No borders at all.
    None,
    /// `+`, `-` and `|`.
    Ascii,
    /// Like `Ascii` but without outer borders.
    Ascii2,
    /// Light box drawing characters with sharp corners.
    Sharp,
    /// Light box drawing characters with rounded corners.
    Rounded,
    /// Light box drawing characters with heavy corners.
    Reinforced,
    /// Markdown table.
    Markdown,
    /// Like `Sharp`, with a rule between every row.
    Grid,
}

impl Style {
    /// Rule drawn above the first row.
    pub fn top(&self) -> Option<Rule> {
        match self {
            Style::None | Style::Ascii2 | Style::Markdown => None,
            Style::Ascii => Some(ASCII_RULE),
            Style::Sharp | Style::Grid => Some(rule("┌", "─", "┬", "┐")),
            Style::Rounded => Some(rule("╭", "─", "┬", "╮")),
            Style::Reinforced => Some(rule("┏", "─", "┬", "┓")),
        }
    }

    /// Rule drawn between the header and the body.
    pub fn header_separator(&self) -> Option<Rule> {
        match self {
            Style::None => None,
            Style::Ascii => Some(ASCII_RULE),
            Style::Ascii2 => Some(rule(" ", "-", "+", " ")),
            Style::Markdown => Some(rule("|", "-", "|", "|")),
            Style::Sharp | Style::Rounded | Style::Reinforced | Style::Grid => Some(LIGHT_MIDDLE),
        }
    }

    /// Rule drawn between two body rows.
    pub fn row_separator(&self) -> Option<Rule> {
        match self {
            Style::Grid => Some(LIGHT_MIDDLE),
            _ => None,
        }
    }

    /// Rule drawn below the last row.
    pub fn bottom(&self) -> Option<Rule> {
        match self {
            Style::None | Style::Ascii2 | Style::Markdown => None,
            Style::Ascii => Some(ASCII_RULE),
            Style::Sharp | Style::Grid => Some(rule("└", "─", "┴", "┘")),
            Style::Rounded => Some(rule("╰", "─", "┴", "╯")),
            Style::Reinforced => Some(rule("┗", "─", "┴", "┛")),
        }
    }

    /// Vertical borders of a row.
    pub fn borders(&self) -> Borders {
        match self {
            Style::None => borders("", "", ""),
            Style::Ascii | Style::Markdown => ASCII_BORDERS,
            Style::Ascii2 => borders(" ", "|", " "),
            Style::Sharp | Style::Rounded | Style::Reinforced | Style::Grid => LIGHT_BORDERS,
        }
    }
}

impl Rule {
    /// Writes the rule so that it spans the given columns.
    ///
    /// `widths` are the content widths of the columns; each column is widened
    /// by `padding` on both sides and the whole line is preceded by `indent`
    /// spaces.
    pub fn write<W: Write>(
        &self,
        out: &mut W,
        widths: &[usize],
        padding: usize,
        indent: usize,
    ) -> io::Result<()> {
        write!(out, "{:indent$}", "")?;
        out.write_all(self.left.as_bytes())?;
        for (i, width) in widths.iter().enumerate() {
            if i > 0 {
                out.write_all(self.cross.as_bytes())?;
            }
            out.write_all(self.fill.repeat(width + 2 * padding).as_bytes())?;
        }
        out.write_all(self.right.as_bytes())?;
        out.write_all(b"\n")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rule_layout() {
        let mut out = Vec::new();
        ASCII_RULE.write(&mut out, &[1, 3], 1, 2).unwrap();
        assert_eq!(String::from_utf8(out).unwrap(), "  +---+-----+\n");

        let mut out = Vec::new();
        ASCII_RULE.write(&mut out, &[], 1, 0).unwrap();
        assert_eq!(String::from_utf8(out).unwrap(), "++\n");
    }

    #[test]
    fn styles_without_outer_borders() {
        for style in [Style::None, Style::Ascii2, Style::Markdown] {
            assert!(style.top().is_none());
            assert!(style.bottom().is_none());
        }
        assert!(Style::None.header_separator().is_none());
        assert!(Style::Grid.row_separator().is_some());
        assert!(Style::Sharp.row_separator().is_none());
    }
}
EOF
